from pocket_coffea.lib.weights import Weight

class ToyReweight(Weight):
    """Custom per-event MC weight with symmetric up/down variations."""
    name = "toy_reweight"
    has_variations = True

    def __init__(self, events):
        self.events = events
        # Normalize to 1
        self.baseline = self.events.LHEWeight_originalXWGTUP.mean()

    def get_nominal(self):
        return self.events.LHEWeight_originalXWGTUP / self.baseline

    def get_variation(self, direction):
        nominal = self.get_nominal()
        if direction == "up":
            return nominal * 1.05
        elif direction == "down":
            return nominal * 0.95
        else:
            raise ValueError(f"Unknown direction: {direction}")


